export const WORDS = {};
for (const L in RAW) WORDS[L] = { all: RAW[L].all.split(" "), common: RAW[L].common.split(" "), nouns: RAW[L].nouns.split(" ") };
const SETS = {};
/** true if `w` (lowercase) is a valid German word of its length */
export function isWord(w) { const L = w.length; if (!WORDS[L]) return false; SETS[L] ||= new Set(WORDS[L].all); return SETS[L].has(w); }
export const UPPER = (w) => w.toUpperCase();
